import base64, os

files = {
    'main.py': '',
    'core/accounts.py': '',
    'core/database.py': '',
    'core/signal_state.py': '',
    'core/breeze_client.py': '',
    'core/order_router.py': '',
    'webhooks/utlrg.py': '',
    'auth/breeze_auth.py': '',
    'api/routes.py': '',
    'strategies/utlrg/expiry.py': '',
    'strategies/utlrg/strike.py': '',
    'frontend/index.html': '',
    'config/nse_holidays.json': '',
    'config/strategies.json': '',
    'scripts/deploy.sh': '',
    'scripts/nginx.conf': '',
    'scripts/smb-algo.service': '',
    '.env': '',
}


base = '/opt/smb-algo'
for path, b64 in files.items():
    full = os.path.join(base, path)
    os.makedirs(os.path.dirname(full), exist_ok=True)
    with open(full, 'wb') as f:
        f.write(base64.b64decode(b64))
    print(f'✓ {path}')
print()
print('All files written successfully!')

